    "path": "chernobylite-trainer/src/ChernobyliteTrainer/MemoryManager.cs",
    "content": "using System.Diagnostics;\nusing System.Runtime.InteropServices;\nusing Microsoft.Extensions.Logging;\n\nnamespace ChernobyliteTrainer;\n\n/// <summary>\n/// Manages low-level Windows memory operations for the Chernobylite process.\n/// </summary>\npublic sealed class MemoryManager : IDisposable\n{\n    private readonly ILogger<MemoryManager> _logger;\n    private IntPtr _processHandle;\n    private int _processId;\n    private bool _disposed;\n\n    // Windows API imports\n    [DllImport(\"kernel32.dll\", SetLastError = true)]\n    private static extern IntPtr OpenProcess(uint dwDesiredAccess, bool bInheritHandle, int dwProcessId);\n\n    [DllImport(\"kernel32.dll\", SetLastError = true)]\n    private static extern bool ReadProcessMemory(IntPtr hProcess, IntPtr lpBaseAddress, byte[] lpBuffer, int dwSize, out int lpNumberOfBytesRead);\n\n    [DllImport(\"kernel32.dll\", SetLastError = true)]\n    private static extern bool WriteProcessMemory(IntPtr hProcess, IntPtr lpBaseAddress, byte[] lpBuffer, int dwSize, out int lpNumberOfBytesWritten);\n\n    [DllImport(\"kernel32.dll\", SetLastError = true)]\n    private static extern bool CloseHandle(IntPtr hObject);\n\n    private const uint ProcessAllAccess = 0x1F0FFF;\n\n    public MemoryManager(ILogger<MemoryManager> logger)\n    {\n        _logger = logger;\n    }\n\n    /// <summary>\n    /// Attaches to the Chernobylite process by name.\n    /// </summary>\n    public bool Attach(string processName = \"Chernobylite\")\n    {\n        var processes = Process.GetProcessesByName(processName);\n        if (processes.Length == 0)\n        {\n            _logger.LogError(\"Process '{ProcessName}' not found.\", processName);\n            return false;\n        }\n\n        _processId = processes[0].Id;\n        _processHandle = OpenProcess(ProcessAllAccess, false, _processId);\n\n        if (_processHandle == IntPtr.Zero)\n        {\n            _logger.LogError(\"Failed to open process {ProcessId}. Error: {ErrorCode}\", _processId, Marshal.GetLastWin32Error());\n            return false;\n        }\n\n        _logger.LogInformation(\"Attached to process {ProcessName} (PID: {ProcessId}).\", processName, _processId);\n        return true;\n    }\n\n    /// <summary>\n    /// Reads a value of type T from the specified memory address.\n    /// </summary>\n    public T? Read<T>(IntPtr address) where T : unmanaged\n    {\n        if (_processHandle == IntPtr.Zero)\n            throw new InvalidOperationException(\"Not attached to a process.\");\n\n        int size = Marshal.SizeOf<T>();\n        byte[] buffer = new byte[size];\n\n        if (!ReadProcessMemory(_processHandle, address, buffer, size, out int bytesRead))\n        {\n            _logger.LogWarning(\"ReadProcessMemory failed at 0x{Address:X8}. Error: {ErrorCode}\", address.ToInt64(), Marshal.GetLastWin32Error());\n            return null;\n        }\n\n        if (bytesRead != size)\n            return null;\n\n        T result = Marshal.PtrToStructure<T>(Marshal.UnsafeAddrOfPinnedArrayElement(buffer, 0));\n        return result;\n    }\n\n    /// <summary>\n    /// Writes a value of type T to the specified memory address.\n    /// </summary>\n    public bool Write<T>(IntPtr address, T value) where T : unmanaged\n    {\n        if (_processHandle == IntPtr.Zero)\n            throw new InvalidOperationException(\"Not attached to a process.\");\n\n        int size = Marshal.SizeOf<T>();\n        byte[] buffer = new byte[size];\n        Marshal.StructureToPtr(value, Marshal.UnsafeAddrOfPinnedArrayElement(buffer, 0), false);\n\n        if (!WriteProcessMemory(_processHandle, address, buffer, size, out int bytesWritten))\n        {\n            _logger.LogWarning(\"WriteProcessMemory failed at 0x{Address:X8}. Error: {ErrorCode}\", address.ToInt64(), Marshal.GetLastWin32Error());\n            return false;\n        }\n\n        return bytesWritten == size;\n    }\n\n    /// <summary>\n    /// Finds a memory address by scanning for a pattern (simple AOB scan stub).\n    /// </summary>\n    public IntPtr? FindPattern(string pattern, int moduleSize = 0x1000000)\n    {\n        // Simplified pattern scan: iterate over a region and compare bytes.\n        // In a real trainer, this would be more robust.\n        byte[] patternBytes = ConvertFromPatternString(pattern);\n        byte[] region = new byte[moduleSize];\n        IntPtr baseAddress = new IntPtr(0x400000); // Typical base for x86 games\n\n        if (!ReadProcessMemory(_processHandle, baseAddress, region, moduleSize, out int bytesRead))\n        {\n            _logger.LogWarning(\"Failed to read module region for pattern scan.\");\n            return null;\n        }\n\n        for (int i = 0; i < bytesRead - patternBytes.Length; i++)\n        {\n            bool match = true;\n            for (int j = 0; j < patternBytes.Length; j++)\n            {\n                if (patternBytes[j] != 0x00 && region[i + j] != patternBytes[j])\n                {\n                    match = false;\n                    break;\n                }\n            }\n            if (match)\n                return IntPtr.Add(baseAddress, i);\n        }\n\n        _logger.LogWarning(\"Pattern not found in memory.\");\n        return null;\n    }\n\n    private static byte[] ConvertFromPatternString(string pattern)\n    {\n        // Example: \"90 90 ?? 0F 84\" -> byte array with wildcards as 0x00\n        var parts = pattern.Split(' ', StringSplitOptions.RemoveEmptyEntries);\n        byte[] result = new byte[parts.Length];\n        for (int i = 0; i < parts.Length; i++)\n        {\n            if (parts[i] == \"??\" || parts[i] == \"?\")\n                result[i] = 0x00; // wildcard\n            else\n                result[i] = Convert.ToByte(parts[i], 16);\n        }\n        return result;\n    }\n\n    public void Dispose()\n    {\n        if (!_disposed && _processHandle != IntPtr.Zero)\n        {\n            CloseHandle(_processHandle);\n            _processHandle = IntPtr.Zero;\n            _disposed = true;\n            _logger.LogInformation(\"Disconnected from process.\");\n        }\n    }\n}\n"
  },
