    "path": "chernobylite-trainer/src/ChernobyliteTrainer/TrainerService.cs",
    "content": "using Microsoft.Extensions.Hosting;\nusing Microsoft.Extensions.Logging;\n\nnamespace ChernobyliteTrainer;\n\n/// <summary>\n/// Core trainer service that applies cheats by writing to known memory addresses.\n/// </summary>\npublic sealed class TrainerService : BackgroundService\n{\n    private readonly MemoryManager _memoryManager;\n    private readonly ILogger<TrainerService> _logger;\n    private readonly Dictionary<string, IntPtr> _addressCache = new();\n\n    // Known offsets for Chernobylite (example values, would be determined via reverse engineering)\n    private const long HealthOffset = 0x00A3F4C0;\n    private const long StaminaOffset = 0x00A3F4C8;\n    private const long ResourceOffset = 0x00B2A100;\n    private const long AmmoOffset = 0x00B2A120;\n    private const long RadiationOffset = 0x00A3F4D0;\n\n    public TrainerService(MemoryManager memoryManager, ILogger<TrainerService> logger)\n    {\n        _memoryManager = memoryManager;\n        _logger = logger;\n    }\n\n    protected override async Task ExecuteAsync(CancellationToken stoppingToken)\n    {\n        _logger.LogInformation(\"Chernobylite Trainer started.\");\n\n        if (!_memoryManager.Attach())\n        {\n            _logger.LogError(\"Could not attach to game. Exiting.\");\n            return;\n        }\n\n        // Resolve addresses (static base + offset)\n        IntPtr baseAddress = new IntPtr(0x400000); // Main module base\n        _addressCache[\"health\"] = IntPtr.Add(baseAddress, HealthOffset);\n        _addressCache[\"stamina\"] = IntPtr.Add(baseAddress, StaminaOffset);\n        _addressCache[\"resources\"] = IntPtr.Add(baseAddress, ResourceOffset);\n        _addressCache[\"ammo\"] = IntPtr.Add(baseAddress, AmmoOffset);\n        _addressCache[\"radiation\"] = IntPtr.Add(baseAddress, RadiationOffset);\n\n        _logger.LogInformation(\"Addresses resolved. Starting cheat loop.\");\n\n        while (!stoppingToken.IsCancellationRequested)\n        {\n            ApplyCheats();\n            await Task.Delay(100, stoppingToken); // 10 Hz update\n        }\n    }\n\n    private void ApplyCheats()\n    {\n        // Infinite Health (float, set to 100.0f)\n        if (_memoryManager.Write(_addressCache[\"health\"], 100.0f))\n            _logger.LogDebug(\"Health set to 100.\");\n\n        // Infinite Stamina (float, set to 100.0f)\n        if (_memoryManager.Write(_addressCache[\"stamina\"], 100.0f))\n            _logger.LogDebug(\"Stamina set to 100.\");\n\n        // Infinite Resources (int, set to 9999)\n        if (_memoryManager.Write(_addressCache[\"resources\"], 9999))\n            _logger.LogDebug(\"Resources set to 9999.\");\n\n        // Unlimited Ammo (int, set to 999)\n        if (_memoryManager.Write(_addressCache[\"ammo\"], 999))\n            _logger.LogDebug(\"Ammo set to 999.\");\n\n        // No Radiation (float, set to 0.0f)\n        if (_memoryManager.Write(_addressCache[\"radiation\"], 0.0f))\n            _logger.LogDebug(\"Radiation set to 0.\");\n    }\n\n    public override void Dispose()\n    {\n        _memoryManager.Dispose();\n        base.Dispose();\n    }\n}\n"
  },
